using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class MalcolmX
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Progress is healing the wound that the blow made. And they haven't even pulled the knife out much less heal the wound. They won't even admit the knife is there.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "We cannot think of uniting with others, until after we have first united among ourselves. We cannot think of being acceptable to others until we have first proven acceptable to ourselves.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "If you aren't careful, the newspapers will have you hating the people who are being oppressed and loving the people who are doing the oppressing.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "We need more light about each other. Light creates understanding, understanding creates love, love creates patience, and patience creates unity.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "I don't mind shaking hands with human beings. Are you one?", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "President Kennedy never foresaw that the chickens would come home to roost so soon. Being an old farm boy myself, chickens coming home to roost never did make me sad; they've always made me glad.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "It's just like when you've got some coffee that's too black, which means it's too strong. What you do? You integrate it with cream; you make it weak. If you pour too much cream in, you won't even know you ever had coffee.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "If you stick a knife in my back nine inches and pull it out six inches, there's no progress. If you pull it all the way out that's not progress. Progress is healing the wound that the blow made.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "There can be no black-white unity until there is first some black unity. There can be no workers' solidarity until there is first some racial solidarity.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "We are African, and we happened to be in America. We're not American. We are people who formerly were Africans who were kidnapped and brought to America. Our forefathers weren't the Pilgrims. The rock was landed on us.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "They don't practice what they preach, whereas South Africa preaches and practices the same thing. I have more respect for a man who lets me know where he stands, even if he's wrong, than the one who comes up like an angel and is nothing but a devil.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "I believe in the brotherhood of all men, but I don't believe in wasting brotherhood on anyone who doesn't want to practice it with me. Brotherhood is a two-way street.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "You get freedom by letting your enemy know that you'll do anything to get your freedom; then you'll get it. It's the only way you'll get it.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "No Negro leaders have fought for civil rights; they have begged for civil rights. They have begged the white man for civil rights. They have begged the white man for freedom. And anytime you beg another man to set you free, you'll never be free.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "The price of freedom is death.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "I'm not going to sit at your table and watch you eat, with nothing on my plate, and call myself a diner. Sitting at the table doesn't make you a diner, unless you eat some of what's on that plate.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "How can you thank a man for giving you what's already yours? How then can you thank him for giving you only part of what's already yours?", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Whenever you are going after something that is yours, you are within your legal rights to lay claim to it. And anyone who puts forth any effort to deprive you of that which is yours, is breaking the law, is a criminal.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "We want freedom now, but we're not going to get it saying \"We Shall Overcome\". We've got to fight until we overcome.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "A segregated school system produces children who, when they graduate, graduate with crippled minds.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "In areas where the government has proven itself either unwilling or unable to defend the lives and the property of Negroes, it's time for Negroes to defend themselves.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "If the white man doesn't want the black man buying rifles and shotguns, then let the government do its job.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "The question tonight, as I understand it, is \"The Negro Revolt, and Where Do We Go From Here? or What Next?\" In my little humble way of understanding it, it points toward either the ballot or the bullet.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "I'm not an American. I'm one of the 22 million black people who are the victims of Americanism. One of the 22 million black people who are the victims of democracy, nothing but disguised hypocrisy.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "I don't see any American dream; I see an American nightmare.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "This government has failed the Negro. This so-called democracy has failed the Negro. And all these white liberals have definitely failed the Negro.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "It'll be liberty, or it will be death. The only difference about this kind of death-it'll be reciprocal.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "It takes two to tango; when I go, you go.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Whenever you're going after something that belongs to you, anyone who's depriving you of the right to have it is a criminal.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Any time you know you're within the law, within your legal rights, within your moral rights, in accord with justice, then die for what you believe in. But don't die alone. Let your dying be reciprocal.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "What's good for the goose is good for the gander.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "We need to expand the civil-rights struggle to a higher level-to the level of human rights. Whenever you are in a civil-rights struggle, whether you know it or not, you are confining yourself to the jurisdiction of Uncle Sam.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "You spend so much time barking up the civil-rights tree, you don't even know there's a human-rights tree on the same floor.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "As long as it's civil rights, this comes under the jurisdiction of Uncle Sam. But the United Nations has what's known as the charter of human rights; it has a committee that deals in human rights.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Civil rights keeps you under his restrictions, under his jurisdiction. Civil rights keeps you in his pocket. Civil rights means you're asking Uncle Sam to treat you right.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "When you expand the civil-rights struggle to the level of human rights, you can then take the case of the black man in this country before the nations in the UN.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "You and I, 22 million African-Americans - that's what we are - Africans who are in America. You're nothing but Africans.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Any time Uncle Sam, with all his machinery for warfare, is held to a draw by some rice eaters, he's lost the battle.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "It takes heart to be a guerrilla warrior because you're on your own.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "A ballot is like a bullet. You don't throw your ballots until you see a target, and if that target is not within your reach, keep your ballot in your pocket.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "We want freedom now, but we're not going to get it saying \"We Shall Overcome\". We've got to fight until we overcome.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "America's conscience is bankrupt. She lost all conscience a long time ago.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Uncle Sam has no conscience. They don't know what morals are.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "A segregated school means a school that is controlled by people who have no real interest in it whatsoever.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "In 1964, it's the ballot or the bullet.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "My religion is my personal business. It governs my personal life, my personal morals.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "And my religious philosophy is personal between me and the God in whom I believe; just as the religious philosophy of these others is between them and the God in whom they believe.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "If we bring up religion, we'll have differences; we'll have arguments; and we'll never be able to get together.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "When you spend your dollar out of the community in which you live, the community in which you spend your money becomes richer and richer; the community out of which you take your money becomes poorer and poorer.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Anytime you have to rely upon your enemy for a job you're in bad shape.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Today it's time to stop singing and start swinging. You can't sing up on freedom, but you can swing up on some freedom.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Once you change your philosophy, you change your thought pattern. Once you change your thought pattern, you change your - your attitude. Once you change your attitude, it changes your behavior pattern and then you go on into some action.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "We don't see any American dream; we've experienced only the American nightmare.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Any time you find the government involved in a conspiracy to violate the citizenship or the civil rights of a people, then you are wasting your time going to that government expecting redress.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Instead, you have to take that government to the World Court and accuse it of genocide and all of the other crimes that it is guilty of today.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "They don't hang you because you're a Baptist; they hang you 'cause you're black.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Cassius Clay can sing, but singing didn't help him to become the heavyweight champion of the world; swinging helped him become the heavyweight champion.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "As long as you gotta sit-down philosophy, you'll have a sit-down thought pattern, and as long as you think that old sit-down thought you'll be in some kind of sit-down action.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Whenever you got a racial powder keg sitting in your lap, you're in more trouble than if you had an atomic powder keg sitting in your lap.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "When a racial powder keg goes off, it doesn't care who it knocks out the way. Understand this, it's dangerous.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Liberty or death was what brought about the freedom of whites in this country from the English.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "I speak as a victim of America's so-called democracy. You and I have never seen democracy; all we've seen is hypocrisy.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "When we open our eyes today and look around America, we see America not through the eyes of someone who has enjoyed the fruits of Americanism, we see through the eyes of someone who has been the victim of Americanism.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "If you're black, you were born in jail. If you're black, you were born in jail, in the North as well as the South.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Long as you south of the Canadian border, you're south.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "A fox and a wolf are both canine, both belong to the dog family. Now you take your choice. You going to choose a Northern dog or a Southern dog?", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Because either dog you choose, I guarantee you'll still be in the dog house.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "It's liberty or it's death. It's freedom for everybody or freedom for nobody.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "You don't have a revolution in which you love your enemy, and you don't have a revolution in which you are begging the system of exploitation to integrate you into it.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Revolutions overturn systems. Revolutions destroy systems.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "She's the only country in history in a position actually to become involved in a bloodless revolution.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "All she's got to do is give the black man in this country everything that's due him, everything.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "The white man can never win another war on the ground. His days of war, victory, his reign, his days of ground victory are over.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Today our people can see that we're faced with a government conspiracy. This government has failed us.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Any kind of activity that takes place on the floor of the Congress or the Senate, it's the government.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "Any kind of dillydallying, that's the government. Any kind of pussyfooting, that's the government.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "As long as you're fighting on the level of civil rights, you're under Uncle Sam's jurisdiction. You're going to his court expecting him to correct the problem.", Author = "Malcolm X" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Malcolm_X", Text = "He created the problem. He's the criminal. You don't take your case to the criminal; you take your criminal to court.", Author = "Malcolm X" },
        };
    }
}
